package com.tduck.cloud.api.ai;
import com.tduck.cloud.form.aiconfig.*;import com.tduck.cloud.form.ai.AiProviderException;import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
public class AiSettingsStreamingTest {
 @Test public void textProjectionHandlesFragmentedEscapesAndDoesNotExposeToolsOrReasoning(){StringBuilder out=new StringBuilder();LiveAnswer.Projection p=new LiveAnswer.Projection("text",out::append);String raw="{\"reasoning\":\"不要显示\",\"findings\":[{\"text\":\"你\\u597d🌟\",\"refs\":[\"S1\"]},{\"text\":\"再见\"}]}";for(char c:raw.toCharArray())p.accept(String.valueOf(c));assertEquals("你好🌟\n\n再见\n\n",out.toString());}
 @Test public void chatDeltasArriveBeforeTheUpstreamFinishes()throws Exception{PipedWriter writer=new PipedWriter();PipedReader reader=new PipedReader(writer);CountDownLatch received=new CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean early=new java.util.concurrent.atomic.AtomicBoolean();Thread upstream=new Thread(()->{try{writer.write("data: {\"choices\":[{\"delta\":{\"content\":\"你\"},\"finish_reason\":null}]}\n\n");writer.flush();early.set(received.await(3,TimeUnit.SECONDS));writer.write("data: {\"choices\":[{\"delta\":{\"content\":\"好\"},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n");writer.close();}catch(Exception ex){throw new RuntimeException(ex);}});upstream.start();String answer=AiTransport.readStream("OPENAI_CHAT",reader,s->received.countDown());upstream.join(4000);assertTrue(early.get());assertEquals("你好",answer);}
 @Test public void allConfiguredProtocolsExtractOnlyPublicText()throws Exception{String responses="data: {\"type\":\"response.output_text.delta\",\"delta\":\"答案\"}\n\ndata: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\"}}\n\n";assertEquals("答案",AiTransport.readStream("OPENAI_RESPONSES",new StringReader(responses),s->{}));String claude="data: {\"type\":\"content_block_delta\",\"delta\":{\"type\":\"thinking_delta\",\"thinking\":\"隐藏\"}}\n\ndata: {\"type\":\"content_block_delta\",\"delta\":{\"type\":\"text_delta\",\"text\":\"答案\"}}\n\ndata: {\"type\":\"message_delta\",\"delta\":{\"stop_reason\":\"end_turn\"}}\n\ndata: {\"type\":\"message_stop\"}\n\n";assertEquals("答案",AiTransport.readStream("ANTHROPIC",new StringReader(claude),s->{}));}
 @Test public void truncatedStreamsAreNotSuccessfulAnswers()throws Exception{try{AiTransport.readStream("OPENAI_CHAT",new StringReader("data: {\"choices\":[{\"delta\":{\"content\":\"半截\"}}]}\n\n"),s->{});fail();}catch(AiProviderException expected){}}
}
